1	package jobs
2	
3	import "slices"
4	
5	// Active is one item of a run that is running or queued on a target.
6	type Active struct {
7		Kind  Kind
8		RunID JobID
9		Item  Item
10	}
11	
12	// ActiveOn returns the running and queued items on target in contextName:
13	// running ones first, then queued ones, each group in run order. The target is
14	// normalized with TargetKey on both sides. With no kinds, every kind is kept.
15	// Items are copied by value, without their cancel hook. No match returns nil.
16	func ActiveOn(runs []Run, contextName, target string, kinds ...Kind) []Active {
17		target = TargetKey(target)
18		var running, queued []Active
19		for _, r := range runs {
20			if r.Context != contextName || (len(kinds) > 0 && !slices.Contains(kinds, r.Kind)) {
21				continue
22			}
23			for _, it := range r.Items {
24				if TargetKey(it.Target) != target {
25					continue
26				}
27				it.cancel = nil
28				a := Active{Kind: r.Kind, RunID: r.ID, Item: it}
29				switch it.State {
30				case ItemRunning:
31					running = append(running, a)
32				case ItemQueued:
33					queued = append(queued, a)
34				}
35			}
36		}
37		return append(running, queued...)
38	}
